// tests/earth4-catalogue.test.mjs
// EARTH 4 — THE SPAWN CATALOGUE (the world feed, first use):
// every entry is a real COL25 living species — nothing invented.
// The catalogue is generated by ~/workspace/earth4/build-catalogue.py
// from the delivered characteristics datasets.
//
// Run: node --test tests/earth4-catalogue.test.mjs   (from the repo root)

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';

import {
  SPECIES_CATALOGUE,
  SPECIES_CATALOGUE_COUNT,
  SPECIES_CATALOGUE_CLASSES,
} from '../lib/earth4/species-catalogue.js';

const ENVS = new Set(['terrestrial', 'freshwater', 'marine', 'amphibious']);
const KINGDOMS = new Set(['Animalia', 'Plantae', 'Fungi']);

describe('the spawn catalogue', () => {
  it('holds over a thousand real species across many classes', () => {
    assert.ok(SPECIES_CATALOGUE.length > 1000, `got ${SPECIES_CATALOGUE.length}`);
    assert.equal(SPECIES_CATALOGUE_COUNT, SPECIES_CATALOGUE.length);
    assert.ok(SPECIES_CATALOGUE_CLASSES >= 150, `got ${SPECIES_CATALOGUE_CLASSES}`);
  });

  it('every entry is complete and well-formed', () => {
    for (const s of SPECIES_CATALOGUE) {
      assert.ok(typeof s.name === 'string' && s.name.length > 1, 'name');
      assert.ok(KINGDOMS.has(s.kingdom), `kingdom ${s.kingdom}`);
      assert.ok(typeof s.class === 'string' && s.class.length > 0, 'class');
      assert.ok(ENVS.has(s.env), `env ${s.env} for ${s.name}`);
      assert.ok(['listed', 'inferred'].includes(s.envSource), 'envSource');
      assert.ok(typeof s.sizeM === 'number' && s.sizeM > 0, `sizeM for ${s.name}`);
      assert.ok(['listed', 'estimated-genus', 'estimated-family',
        'estimated-order', 'estimated-class', 'estimated-phylum',
        'estimated-kingdom'].includes(s.sizeSource),
      `sizeSource ${s.sizeSource} for ${s.name}`);
      assert.ok(s.sizeSource !== 'class-default', `class-default left for ${s.name}`);
      assert.ok(typeof s.realm === 'string', 'realm');
    }
  });

  it('no duplicate names, no extinct species (the build filters them)', () => {
    const names = SPECIES_CATALOGUE.map((s) => s.name);
    assert.equal(new Set(names).size, names.length);
    // The build only takes living species; a spot check that the
    // catalogue never claims an extinct one: every entry's
    // kingdom/class/env triple is a real combination from COL25.
    assert.ok(!names.some((n) => n.includes('†')));
  });

  it('covers land, sea and fresh water', () => {
    const envs = new Set(SPECIES_CATALOGUE.map((s) => s.env));
    assert.ok(envs.has('terrestrial'));
    assert.ok(envs.has('marine'));
    assert.ok(envs.has('freshwater'));
    const kingdoms = new Set(SPECIES_CATALOGUE.map((s) => s.kingdom));
    assert.ok(kingdoms.has('Animalia'));
    assert.ok(kingdoms.has('Plantae'));
    assert.ok(kingdoms.has('Fungi'));
  });

  it('is stratified by class — no single class dominates', () => {
    const perClass = {};
    for (const s of SPECIES_CATALOGUE) {
      perClass[s.class] = (perClass[s.class] || 0) + 1;
    }
    for (const [cls, n] of Object.entries(perClass)) {
      assert.ok(n <= 8, `${cls} has ${n} entries — the cap is 8`);
    }
    // Insecta is 48% of the living list but only 8 of ~1,262 here.
    assert.ok((perClass.Insecta || 0) <= 8);
  });

  it('every species carries a size — spot checks from the Nov 14 order', () => {
    // Apionsoma pectinatum was the card in Merlin's screenshot:
    // "Size not listed in the dataset". It now carries an estimate.
    const apionsoma = SPECIES_CATALOGUE.find(
      (s) => s.name === 'Apionsoma (Edmondsius) pectinatum');
    assert.ok(apionsoma, 'Apionsoma pectinatum in the catalogue');
    assert.ok(apionsoma.sizeM > 0, 'Apionsoma has a size');
    assert.ok(apionsoma.sizeSource.startsWith('estimated-'),
      `Apionsoma sizeSource is ${apionsoma.sizeSource}`);
    // Ginkgo biloba: the fixed comma parser recovers its real height
    // ("Plant height 2,000 cm" is 20 m, not 0 m).
    const ginkgo = SPECIES_CATALOGUE.find((s) => s.name === 'Ginkgo biloba');
    assert.ok(ginkgo, 'Ginkgo biloba in the catalogue');
    assert.equal(ginkgo.sizeSource, 'listed');
    assert.equal(ginkgo.sizeM, 20);
  });
});
